changeSet.sql:
create type rule_type as enum ('GRU_V1');
create type rule_state as enum ('AVAILABLE', 'DEPRECATED', 'UNAVAILABLE');
create table dac_automation_rules
(
  id          bigint generated by default as identity,
  rule_type   rule_type  not null,
  description text       not null,
  rule_state  rule_state not null
);
